const matrix=JSON.parse(document.querySelector('#matrix-data').textContent),winner=document.querySelector('#winner'),body=document.querySelector('#scores');function run(){const weights=Object.fromEntries([...document.querySelectorAll('input[type=range]')].map(x=>[x.dataset.id,Number(x.value)])),scores=matrix.options.map(o=>({option:o,score:matrix.criteria.reduce((n,c)=>n+weights[c.id]*o.ratings[c.id],0)/Math.max(1,matrix.criteria.reduce((n,c)=>n+weights[c.id],0))})).sort((a,b)=>b.score-a.score||a.option.id.localeCompare(b.option.id));winner.textContent=scores[0].option.label[document.documentElement.lang];body.innerHTML=scores.map((x,i)=>'<tr class="'+(i===0?'winner':'')+'"><td>'+x.option.label[document.documentElement.lang]+'</td><td>'+x.score.toFixed(2)+'</td></tr>').join('')}for(const input of document.querySelectorAll('input'))input.addEventListener('input',()=>{input.closest('.criterion').querySelector('output').value=input.value});document.querySelector('#compare').addEventListener('click',run);run();
